export const COMPOUND_MAP=Object.freeze({width:WIDTH,height:HEIGHT,tile_size:32,rooms,doors,props,walls:[...WALL_SET].map(value=>{const [x,y]=value.split(',').map(Number);return{x,y};}),escape_routes:ESCAPE_PLANS.map(plan=>({...plan,requires:[...new Set(plan.stages.flatMap(stage=>stage.requires))]}))});
